package org.cttelsamicsterrassa.data.core.application.player.find;
import org.albertsanso.commons.query.*; import org.cttelsamicsterrassa.data.core.domain.player.model.FederatedPlayer; import org.cttelsamicsterrassa.data.core.domain.player.repository.FederatedPlayerRepository; import javax.inject.*;
@Named public class FindFederatedPlayerByIdQueryHandler extends DomainQueryHandler<FindFederatedPlayerByIdQuery,FederatedPlayer>{private final FederatedPlayerRepository r;@Inject public FindFederatedPlayerByIdQueryHandler(FederatedPlayerRepository r){this.r=r;}public DomainQueryResponse<FederatedPlayer> handle(FindFederatedPlayerByIdQuery q){return r.findFederatedPlayerById(q.getFederatedPlayerId()).map(DomainQueryResponse::sucessResponse).orElseGet(()->DomainQueryResponse.failResponse(null));}}
